-- Purpose: original physical denomination and tender props. API: piece(centavos,x,y,w,h),bundle(counts,x,y). Dependencies: theme/outline/format/widgets only.
local T=require('src.ui.theme'); local O=require('src.ui.draw.outline'); local W=require('src.ui.widgets'); local F=require('src.ui.format'); local Fonts=require('src.ui.fonts'); local Money={}
function Money.piece(denomination,x,y,w,h) if denomination<=1000 then local radius=math.min(w,h)*.43; O.ellipse(x+w/2,y+h/2,radius,radius,T.mustard,1.1); O.ellipse(x+w/2,y+h/2,radius*.8,radius*.8,T.mustard,.7); W.text(F.money(denomination),x+2,y+h/2-10,17,T.ink,w-4,'center') else local colors={[2000]=T.sage,[5000]=T.dustyrose,[10000]=T.teal,[50000]=T.mustard,[100000]=T.steel}; O.rect(x+4,y+7,w-8,h-14,colors[denomination] or T.sage,4); O.rect(x+10,y+13,w-20,h-26,T.paper,2,.7); O.ellipse(x+25,y+h/2,10,h*.22,colors[denomination] or T.sage,.7); local size=18; while size>1 and Fonts.get(size):getWidth(F.money(denomination))>w-48 do size=size-1 end; W.text(F.money(denomination),x+33,y+h/2-size/2,size/(W.textScale or 1),T.ink,w-44,'center'); O.line({x+w-13,y+20,x+w-13,y+h-20},T.maroon,.8) end end
function Money.bundle(counts,x,y) local column=0; for _,denomination in ipairs(require('data.tuning').denominations) do local count=counts and counts[denomination] or 0; if count>0 then Money.piece(denomination,x+column*104,y,96,52); W.text('x '..count,x+column*104,y+52,16,T.ink,96,'center'); column=column+1 end end end
return Money

